def build_cells():
    """Recorrido autónomo. El login LMS nunca es un prerrequisito."""
    cells=[md(x["source"]) if x["kind"]=="md" else code(x["source"]) for x in CELLS]
    for i in (1,3,5,7,12,15,18,20):
        cells[i]["metadata"]["cellView"]="form"
    for i in (9,11,14):
        cells[i]["metadata"].pop("cellView",None)
        cells[i]["metadata"].pop("jupyter",None)
    return cells

def build_notebook():
    return {
        "nbformat": 4,
        "nbformat_minor": 5,
        "metadata": {
            "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
            "language_info": {"name": "python", "version": "3.10.0"},
        },
        "cells": build_cells(),
    }

